def rings(bs,n):
    out=[[bs[-1][0]]*(2*n-2) for _ in range(2*n-2)]
    y=0
    for c,t in bs:
        for i in range(y,y+t):
            out[i][y:len(out)-y]=[c]*(len(out)-2*y)
            out[-1-i][y:len(out)-y]=[c]*(len(out)-2*y)
        for i in range(y,len(out)-y):
            out[i][y:y+t]=[c]*t
            out[i][len(out)-y-t:len(out)-y]=[c]*t
        y+=t
    return out
